// The longer arc starts after the planned knight/Grandma/collector story.
export const EPISODES=[
  {id:'workyard',name:'The Abandoned Workyard',chapter:'The Collector’s Echo',ground:'grass',palette:['#354440','#435547','#53644d','#829267'],boss:'The Scrap Marshal',speaker:'Rowan',kind:'portrait',
    arrival:['The collector is in custody, and Grandma’s gold paid for Rowan’s family’s medicine. For one afternoon, the shop is peaceful. Then every lantern in the dungeon goes out.','Rowan returns with the official’s confiscated notebook. He ordered an ancient machine restarted before his arrest. “He called it a treasure pump. Pip, something is still running.”'],
    ending:['The workyard is full of armour assembled from stolen tools. The marshal’s orders name no monsters at all—only “remove occupants.” The bounty was a cover for emptying the dungeon.','Pip finds a cart loaded with family-shop crates. Silk’s handwriting is still on the labels. “Those were gifts,” he says. Rowan kneels beside him. “Then we take them back.”','A brass conduit runs deeper into the foundry. The machine can keep following its orders even without the collector. They must cut its supply before anyone else is hurt.'],note:'“We saved our family. Now we finish what he started.”'},
  {id:'foundry',name:'The Lantern Foundry',chapter:'The Collector’s Echo',ground:'stone',palette:['#514044','#604a4c','#705858','#a87a60'],boss:'The Furnace Keeper',speaker:'Uncle Bones',kind:'skeleton',
    arrival:['Uncle Bones insists on coming. He remembers the foundry from before his knees became “historical monuments.” Every lantern in the dungeon was once made here.','The stolen treasure feeds a furnace beneath the floor. Melted gold carries an enchantment down the brass conduits. The keeper has been told to burn until nothing is left.'],
    ending:['Bones turns the ancient shut-off wheel while Pip holds the keeper’s falling gate. For a moment Pip thinks his arms will give way. Rowan braces the gate beside him. He does not have to hold it alone.','They rescue the trapped lantern-makers and return the unopened shop crates. Among them is a knitted scarf labelled “Pip—when he finally grows.” Silk refuses to explain the label.','The furnace stops, but a pulse still moves through the conduits. Three old wards are broken. Bones remembers who repaired the first one: the weavers of the whispering woods.'],note:'“Uncle Bones has excellent timing. Terrible knees.”'},
  {id:'rootgrove',name:'The Whispering Root Grove',chapter:'A Thread Worth Keeping',ground:'grass',palette:['#293f43','#355452','#41685a','#759675'],boss:'The Rootbound Sentinel',speaker:'Silk',kind:'spider',
    arrival:['Silk closes the shop for the first time in years. “Family emergency. No refunds on potatoes.” She brings a basket of thread and enough tea for a small army.','The ward is woven through living roots. The collector’s workers cut it to drag treasure carts through. Now the woods repeat every frightened thought the travellers have.'],
    ending:['Pip hears the roots whisper that he is too small to matter. Silk hears that her strange family will never belong. Rowan hears that she nearly killed the people who raised her friend.','They answer aloud. Pip names the family who chose him. Silk says she belongs wherever they do. Rowan admits what she did, and promises to help put it right. The roots grow quiet.','A torn silver thread leads to the old weaving hall. Silk follows it carefully. “Everything can be repaired,” she says. “Some things simply need more patience.”'],note:'“The trees are rude. Silk is ruder back.”'},
  {id:'weaverhall',name:'The Silver Weaving Hall',chapter:'A Thread Worth Keeping',ground:'stone',palette:['#474054','#584b68','#66597a','#9888a7'],boss:'The Tangled Loom',speaker:'Silk',kind:'spider',
    arrival:['The weaving hall is older than the shop. Its empty looms still move, dragging broken ward-thread across the floor. A repair spell has mistaken every visitor for another loose strand.','Silk asks Pip to protect the great loom while she untangles it. Rowan keeps count of the approaching constructs. “How long?” Silk smiles. “Never ask a knitter that.”'],
    ending:['Pip breaks the spell’s iron casing without touching the fragile thread inside. Silk stitches the ward together. The restless looms slow, then stop. The woods outside brighten.','Rowan offers to pay for Silk’s work. Silk gives her a scarf instead. “You’re helping my brother. You can learn to accept presents.” It is long enough to wrap around her armour twice.','The repaired ward reveals a map of the other two seals: a beacon on the storm coast and a chamber beneath a fallen star. Pip folds it beside his family portrait.'],note:'“Apparently saving the world involves knitting.”'},
  {id:'stormshore',name:'The Stormglass Shore',chapter:'A Light for the Lost',ground:'grass',palette:['#334653','#40586a','#4e7180','#92adb0'],boss:'The Tideguard',speaker:'Rowan',kind:'portrait',
    arrival:['The coast is full of abandoned boats. Without the beacon, adventurers who once shopped with Pip have been unable to find the safe road home. The royal sentries took their lamps.','Rowan recognises a battered training shield among the cargo. Her younger brother made the painted flower on it. She writes him a letter while Pip makes tea.'],
    ending:['They free the road from the tideguard’s patrol. Pip finds three stranded travellers sheltering behind a cart. One recognises the little shopkeeper. “You sell socks,” she says. “I do other things too,” Pip replies.','Rowan reads her brother’s reply at the next camp. Their mum is recovering. They want her home, but they understand why she is staying to help. For the first time, the bounty money no longer feels like a debt.','Above the shore, the beacon is dark. Its glass lens has been wrapped in the same brass conduits they found at the furnace. Another keeper waits at the top.'],note:'“One day I will have an adventure that stays dry.”'},
  {id:'beacon',name:'The Unlit Beacon',chapter:'A Light for the Lost',ground:'stone',palette:['#3c465d','#4c5970','#5d6d84','#9aabc0'],boss:'The Glass Warden',speaker:'Rowan',kind:'portrait',
    arrival:['The beacon’s stairs climb around a sleeping crystal. Old carvings show humans and monsters carrying lanterns together. The collector painted over every monster’s face.','Rowan scrapes a patch of paint away with her sword. “I should have asked more questions.” Pip lights the first stair lamp. “You’re asking them now.”'],
    ending:['When the warden falls, Pip holds the lens steady while Rowan removes the conduits. Its light crosses the shore. Far below, the stranded travellers lift their lamps in reply.','The second ward wakes. It sends a clear note through the crystal, and the machine beneath the dungeon loses part of its strength. The danger can be stopped. It is no longer just a hope.','A final carving points towards the fallen-star chamber. It bears a tiny handprint beside the words: “The heart chose a keeper.” Bones has seen that handprint before.'],note:'“The coast has its light back. So do we.”'},
  {id:'starpass',name:'The Fallen-Star Pass',chapter:'One in a Million',ground:'grass',palette:['#3a394e','#4e4963','#635875','#9b8ca9'],boss:'The Meteor Knight',speaker:'Uncle Bones',kind:'skeleton',
    arrival:['Bones tells Pip how the family found him as a baby beside a broken dungeon lantern. Grandma warmed him in her wings. Silk knitted an apron before anyone remembered to buy ordinary clothes.','A million lanterns had gone dark that night. One kept glowing when Pip touched it. They did not know what it meant. They only knew he needed a home.'],
    ending:['The meteor knight guards a path scattered with old nursery charms. Pip recognises the little wooden bird Grandma kept on the shop shelf. He had thought every family owned one.','Bones admits they feared someone would take Pip away if they knew about his strength. “We weren’t keeping you weak. We wanted you to have a childhood.” Pip takes his hand. “I did.”','Beyond the pass, the star chamber has opened. The old keeper’s records may explain the lantern, the handprint, and why the machine responds whenever Pip draws his sword.'],note:'“They chose me before they knew I was strong.”'},
  {id:'starvault',name:'The Fallen-Star Chamber',chapter:'One in a Million',ground:'stone',palette:['#373a55','#474c70','#59618c','#9298bd'],boss:'The Starbound Guardian',speaker:'Pip',kind:'portrait',
    arrival:['The chamber records a gift so rare that the old keepers called it one in a million. Its bearer can hear the dungeon’s heart and redirect the strength that protects its inhabitants.','The gift is neither a title nor a command. Every record warns the same thing: a keeper who sees people only as treasure to possess will break the heart they are meant to protect.'],
    ending:['Pip opens the final ward by naming the people he wants to protect. He names Bones, Silk, Grandma, and Rowan. Then the lantern-makers, the stranded travellers, and the family waiting for Rowan at home.','The guardian bows. The gift did not make Pip kind. His family taught him that. The strength followed when he began acting on it. He is still frightened, and still wearing the wrong size apron.','All three wards are repaired. The heart’s emergency gate opens beneath the dungeon. The machine is trapped inside, struggling against its last orders. Pip and Rowan set out together.'],note:'“Being rare is less useful than knowing who matters.”'},
  {id:'heartgate',name:'The Heart’s Emergency Gate',chapter:'A Home Worth Saving',ground:'stone',palette:['#4e3b45','#614a55','#735b60','#a98b79'],boss:'The Brass Colossus',speaker:'Grandma',kind:'dragon',
    arrival:['Grandma waits at the emergency gate with a sack of birthday presents. Every other resident has been led to safety. She refuses to leave her grandson to carry the last part alone.','The colossus holds the gate shut while the machine pulls treasure towards its core. Grandma braces the stonework. Rowan watches its blade. Pip takes one slow breath.'],
    ending:['The gate opens. Pip hears the heart clearly for the first time: it is not asking him to destroy anything. It is asking him to stop a command that no longer makes sense.','Grandma gives him the wooden bird from the shop shelf. “You were never our little miracle,” she says. “You were our little one. That came first.” Pip puts it safely inside his apron.','The family stays behind to hold the way out open. Rowan steps beside Pip. The core has one final guardian, and beyond it a broken brass command-key. They know what must be done.'],note:'“Grandma brought presents to a siege. Of course she did.”'},
  {id:'heartcore',name:'The Dungeon Heart',chapter:'A Home Worth Saving',ground:'stone',palette:['#443c51','#5b5069','#71657c','#b59da1'],boss:'The Last Command',speaker:'Pip and Rowan',kind:'portrait',
    arrival:['The command-key repeats the collector’s orders: empty the dungeon, seize the treasure, remove anyone who objects. The last guardian follows without understanding a single word.','Rowan raises her sword, then looks at Pip. “Your family. Our home. We do this together.” The heart lights their way through the final chamber.'],
    ending:['Pip holds the command-key while Rowan cuts its brass links. When the guardian stops moving, Pip gives the heart a new instruction: keep the doors open for the people who live here.','The stolen treasure returns to its owners. The official’s notebook becomes evidence, and the lantern-makers tell the kingdom what the false bounty really meant. Rowan returns home to see her mum before coming back for tea.','Bones gets a chair behind the shop counter. Silk opens a second till. Grandma gives everyone presents, including several people who had only come in for socks. Pip keeps his battered apron.','He is one in a million. He is also the shopkeeper who remembers your name. Tomorrow there will be deliveries, tea, and another family dinner. Tonight, everyone is home.'],note:'“Turns out I did come back. Please stop watering the gold.”'}
];

export const CAMPAIGN_IDS=EPISODES.map(e=>e.id);
export function campaignArea(step){
  const e=EPISODES[step-1],bossId=e.id+'-boss';
  return {...e,id:e.id,campaignStep:step,caption:'Clear the constructs, then talk to '+e.speaker+'.',spawn:{x:352,y:414},
    exits:[{id:'south',x:352,y:441,to:step===1?'hollow':EPISODES[step-2].id,spawn:step===1?{x:466,y:355}:{x:352,y:80},label:step===1?'Return to the family shop':'Return to the previous road'},...(step<EPISODES.length?[{id:'north',x:352,y:49,to:EPISODES[step].id,spawn:{x:352,y:414},label:'Continue the journey'}]:[])],
    chests:[{id:e.id+'-wood',type:'wood',x:226,y:330},{id:e.id+'-iron',type:'iron',x:461,y:254},{id:e.id+'-gold',type:'gold',x:448,y:110,lockedBy:bossId}],
    enemies:[...[[286,346],[411,318],[290,235],[420,183]].map(([x,y],i)=>({id:e.id+'-guard-'+i,kind:'guard',x,y,hp:58+step*6,damage:9+Math.floor(step/3),xp:15,coins:15,name:'Enchanted construct'})),{id:bossId,kind:'boss',x:352,y:167,hp:200+step*24,damage:12+Math.floor(step/2),xp:40,coins:50,name:e.boss}],
    npcs:[{id:'campaign-lore',kind:e.kind,x:352,y:94,label:'Talk to '+e.speaker}]};
}
